using Health_Care_System.BLL.Interfaces; using Health_Care_System.Data; using Health_Care_System.Entities;
namespace Health_Care_System.BLL.Implementations;
public sealed class UnitOfWork:IUnitOfWork { private readonly AppDbContext _context; private readonly Lazy<IGenericRepository<Patient>> _patients; private readonly Lazy<IGenericRepository<Doctor>> _doctors; private readonly Lazy<IAppointmentRepository> _appointments; public IGenericRepository<Patient> Patients=>_patients.Value; public IGenericRepository<Doctor> Doctors=>_doctors.Value; public IAppointmentRepository Appointments=>_appointments.Value; public UnitOfWork(AppDbContext context){_context=context;_patients=new(()=>new GenericRepository<Patient>(_context));_doctors=new(()=>new GenericRepository<Doctor>(_context));_appointments=new(()=>new AppointmentRepository(_context));} public Task<int> SaveChangesAsync()=>_context.SaveChangesAsync(); }
